#include <map>
#include <optional>
#include <string>

std::optional<std::string> resolve(const std::string& path, const std::map<std::string, std::string>& links)
{
    std::string current{ path };
    for (int replacements{ 0 }; ; ++replacements)
    {
        const std::string* bestName{ nullptr };
        const std::string* bestTarget{ nullptr };
        for (const auto& [name, target] : links)
        {
            if (current.compare(0, name.size(), name) != 0) continue;              // not a prefix
            if (current.size() > name.size() && current[name.size()] != '\\') continue;   // not a whole component
            if (!bestName || name.size() > bestName->size()) { bestName = &name; bestTarget = &target; }
        }
        if (!bestName) return current;
        if (replacements == 16) return std::nullopt;                               // a loop
        current = *bestTarget + current.substr(bestName->size());
    }
}

unitTests:
const std::map<std::string, std::string> links{
    { "\\??\\C:", "\\Device\\HarddiskVolume3" },
    { "\\??\\Echo", "\\Device\\XenonEcho" },
};
TEST("a drive path") { CHECK_EQ(*resolve("\\??\\C:\\Games\\save.dat", links), std::string("\\Device\\HarddiskVolume3\\Games\\save.dat")); }
TEST("a device link on its own") { CHECK_EQ(*resolve("\\??\\Echo", links), std::string("\\Device\\XenonEcho")); }
TEST("not a whole component") { CHECK_EQ(*resolve("\\??\\Cx\\file", links), std::string("\\??\\Cx\\file")); }
TEST("no link applies") { CHECK_EQ(*resolve("\\Device\\Null", links), std::string("\\Device\\Null")); }
TEST("links to links") { const std::map<std::string, std::string> chain{ { "\\A", "\\B\\x" }, { "\\B", "\\C" } }; CHECK_EQ(*resolve("\\A\\y", chain), std::string("\\C\\x\\y")); }
TEST("the longest link wins") { const std::map<std::string, std::string> l{ { "\\A", "\\one" }, { "\\A\\B", "\\two" } }; CHECK_EQ(*resolve("\\A\\B\\c", l), std::string("\\two\\c")); }
TEST("a loop is detected") { const std::map<std::string, std::string> loop{ { "\\X", "\\Y" }, { "\\Y", "\\X" } }; CHECK(!resolve("\\X\\z", loop).has_value()); }

